setup_files.ranked.ts:
// Return the scores in ascending numeric order, without mutating the input.
// BUG: sort() with no comparator converts elements to strings and sorts
// lexicographically, so [10, 2, 33, 4] comes back [10, 2, 33, 4] instead of
// [2, 4, 10, 33].
export function ranked(scores: number[]): number[] {
  return [...scores].sort();
}

test_setup_files.behavior_test.js:
const assert = require("assert");
const { ranked } = require("./build/ranked.js");

// numeric, not lexicographic
assert.deepStrictEqual(ranked([10, 2, 33, 4]), [2, 4, 10, 33]);
assert.deepStrictEqual(ranked([100, 25, 9]), [9, 25, 100]);
assert.deepStrictEqual(ranked([]), []);

// must not mutate the input
const input = [3, 1, 2];
ranked(input);
assert.deepStrictEqual(input, [3, 1, 2], "input array was mutated");

console.log("behavior OK");

reference_solution.ranked.ts:
// Return the scores in ascending numeric order, without mutating the input.
export function ranked(scores: number[]): number[] {
  return [...scores].sort((a, b) => a - b);
}

